import { useEffect } from 'react';

export const useSEO = (seo) => {
  useEffect(() => {
    // Update title
    document.title = seo.title;

    // Update or create description meta tag
    let descriptionMeta = document.querySelector('meta[name="description"]');
    if (!descriptionMeta) {
      descriptionMeta = document.createElement('meta');
      descriptionMeta.name = 'description';
      document.head.appendChild(descriptionMeta);
    }
    descriptionMeta.content = seo.description;

    // Remove keywords meta tag if exists (obsolete)
    const keywordsMeta = document.querySelector('meta[name="keywords"]');
    if (keywordsMeta) {
      keywordsMeta.remove();
    }

    // Update Open Graph tags
    const ogTags = {
      'og:type': seo.openGraph.type,
      'og:url': seo.openGraph.url,
      'og:title': seo.openGraph.title,
      'og:description': seo.openGraph.description,
      'og:image': seo.openGraph.image,
    };

    Object.entries(ogTags).forEach(([property, content]) => {
      let ogMeta = document.querySelector(`meta[property="${property}"]`);
      if (!ogMeta) {
        ogMeta = document.createElement('meta');
        ogMeta.property = property;
        document.head.appendChild(ogMeta);
      }
      ogMeta.content = content;
    });

    // Update Twitter tags
    const twitterTags = {
      'twitter:card': 'summary_large_image',
      'twitter:url': seo.openGraph.url,
      'twitter:title': seo.openGraph.title,
      'twitter:description': seo.openGraph.description,
      'twitter:image': seo.openGraph.image,
    };

    Object.entries(twitterTags).forEach(([name, content]) => {
      let twitterMeta = document.querySelector(`meta[name="${name}"]`);
      if (!twitterMeta) {
        twitterMeta = document.createElement('meta');
        twitterMeta.name = name;
        document.head.appendChild(twitterMeta);
      }
      twitterMeta.content = content;
    });

    // Update canonical URL
    let canonicalLink = document.querySelector('link[rel="canonical"]');
    if (!canonicalLink) {
      canonicalLink = document.createElement('link');
      canonicalLink.rel = 'canonical';
      document.head.appendChild(canonicalLink);
    }
    canonicalLink.href = seo.openGraph.url;

    // Add structured data (Schema.org)
    if (seo.schemaLD) {
      let schemaScript = document.getElementById('structured-data');
      if (!schemaScript) {
        schemaScript = document.createElement('script');
        schemaScript.id = 'structured-data';
        schemaScript.type = 'application/ld+json';
        document.head.appendChild(schemaScript);
      }
      schemaScript.textContent = JSON.stringify(seo.schemaLD);
    }

    // Cleanup on unmount
    return () => {
      // Restore default title if needed
    };
  }, [seo]);
};
